import { createRequire } from 'node:module'
import { readFile } from 'node:fs/promises'

const require = createRequire(String.raw`D:\repository\门户H5\package.json`)
const { chromium } = require('playwright')

const port = Number(process.argv[2] || 9222)
const baseUrl = 'http://127.0.0.1:8095/'
const screenshotPath = String.raw`D:\repository\苏住房防汛C端-wt-home-visual\.task-state\home-visual-screenshot.png`
const referencePath = String.raw`C:\Users\Administrator\.dsh\attachments\v1\objects\ed\ede7388538d2bdd2b1dec36445cdf42bc229121bc6ce054b029c99d34cdd146a`
const referenceDataUrl = `data:image/webp;base64,${(await readFile(referencePath)).toString('base64')}`

const studyRows = [
  {
    richTextId: 'visual-study-1',
    title: '2026年度全市住宅小区物业管理综合评价考核实操与打分规范要点解读',
    typeName: '业务培训',
    publishTime: '2026-10-18 09:00:00',
    learnNum: 2340,
  },
  {
    videoId: 'visual-study-2',
    title: '苏州市智慧物业监管平台自查自纠与工单整改全流程操作实务',
    typeName: '实操指南',
    durationText: '15分钟',
    contentType: 'video',
    coverUrl: 'https://visual.invalid/study-thumb.png',
  },
]

const newsRows = [
  {
    richTextId: 'visual-news-1',
    title: '苏州市召开2026年第四季度住宅小区物业服务品质提升现场推进会',
    publishUnit: '市住建局物业管理处',
    publishTime: '2026-10-22 09:00:00',
    readNum: 1580,
    previewSite: 'https://visual.invalid/news-thumb.png',
  },
  {
    richTextId: 'visual-news-2',
    title: '全面推行物业“双晒”公示，让公共收益在阳光下规范运行',
    typeName: '重点聚焦',
    publishTime: '2026-10-15 09:00:00',
    readNum: 3120,
  },
  {
    richTextId: 'visual-news-3',
    title: '关于表彰2026年苏州市智慧物业标杆示范示范小区的决定',
    typeName: '红榜公示',
    publishTime: '2026-10-08 09:00:00',
    readNum: 4890,
  },
]

const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`)
const context = await browser.newContext({
  viewport: { width: 414, height: 1189 },
  deviceScaleFactor: 2,
})
const page = await context.newPage()
const apiPaths = []
const pageErrors = []
page.on('pageerror', error => pageErrors.push(error.message))

const cropData = await page.evaluate(async source => {
  const image = new Image()
  image.src = source
  await new Promise((resolve, reject) => {
    image.onload = resolve
    image.onerror = () => reject(new Error('Unable to decode reference image'))
  })
  const crops = {
    study: { x: 560, y: 1245, width: 220, height: 140 },
    news: { x: 560, y: 1845, width: 220, height: 140 },
  }
  return Object.fromEntries(Object.entries(crops).map(([key, rect]) => {
    const canvas = document.createElement('canvas')
    canvas.width = rect.width
    canvas.height = rect.height
    canvas.getContext('2d').drawImage(image, rect.x, rect.y, rect.width, rect.height, 0, 0, rect.width, rect.height)
    return [key, canvas.toDataURL('image/png')]
  }))
}, referenceDataUrl)

const imageBuffers = Object.fromEntries(Object.entries(cropData).map(([key, dataUrl]) => [
  key,
  Buffer.from(dataUrl.split(',')[1], 'base64'),
]))

await page.route('**/api/**', async route => {
  const path = new URL(route.request().url()).pathname
  apiPaths.push(path)
  let payload = { code: 200, msg: 'ok', data: {} }
  if (path.endsWith('/v2.0/property/msg/page')) {
    payload = { total: 1, rows: [{ msgId: 'visual-notice-1', msgTitle: '关于切实做好住宅小区安全生产排查与风险隐患整改工作的通知' }] }
  } else if (path.endsWith('/v2.0/flowable/task/todoTaskList')) {
    payload = { total: 12, rows: [{ submitTittle: '物业服务合同备案审核', startDeptName: '东渚财富广场' }] }
  } else if (path.endsWith('/v2.0/article/portal/getStudyList')) {
    payload = { total: studyRows.length, rows: studyRows }
  } else if (path.endsWith('/v2.0/article/richText/page')) {
    payload = { total: newsRows.length, rows: newsRows }
  } else if (path.endsWith('/v2.0/system/banner/page')) {
    payload = {
      total: 1,
      rows: [{
        organizationName: '苏州市住房和城乡建设局',
        title: '苏州市智慧物业数字监管协同平台',
        subtitle: '党建引领 · 闭环监督 · 标杆示范 · 智治惠民',
      }],
    }
  }
  await route.fulfill({ status: 200, contentType: 'application/json; charset=utf-8', body: JSON.stringify(payload) })
})

await page.route('https://visual.invalid/**', async route => {
  const url = route.request().url()
  const key = url.includes('study-thumb.png') ? 'study' : 'news'
  await route.fulfill({ status: 200, contentType: 'image/png', body: imageBuffers[key] })
})

try {
  await page.goto(baseUrl, { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(500)
  const storageReady = await page.evaluate(() => {
    if (typeof window.uni?.setStorageSync !== 'function') return false
    window.uni.setStorageSync('flood-token-v1', 'visual-only-token')
    window.uni.setStorageSync('flood-login-user-v1', JSON.stringify({ userId: 'visual-user', userName: 'visual-only', nickName: '截图校验' }))
    return window.uni.getStorageSync('flood-token-v1') === 'visual-only-token'
  })
  if (!storageReady) throw new Error('uni-app H5 storage API was not available for the temporary screenshot session')

  await page.reload({ waitUntil: 'domcontentloaded' })
  await page.waitForFunction(() => {
    const content = document.querySelector('.screen-content')?.textContent || ''
    return content.includes('物业服务合同备案审核') && content.includes('苏州市智慧物业数字监管协同平台')
  }, null, { timeout: 15000 })
  await page.waitForTimeout(400)

  const dimensions = await page.evaluate(() => ({
    viewport: { width: window.innerWidth, height: window.innerHeight, dpr: window.devicePixelRatio },
    document: { width: document.documentElement.scrollWidth, height: document.documentElement.scrollHeight },
    articleCards: document.querySelectorAll('.article-card').length,
  }))
  await page.screenshot({ path: screenshotPath, fullPage: false })
  console.log(JSON.stringify({ screenshotPath, dimensions, apiPaths, pageErrors }))
} finally {
  await context.close()
  await browser.close()
}
